CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles(id uuid PRIMARY KEY, name text NOT NULL, phone text, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_admins(user_id uuid PRIMARY KEY REFERENCES profiles(id));
CREATE TABLE organization_members(organization_id uuid REFERENCES organizations(id),user_id uuid REFERENCES profiles(id),role text NOT NULL CHECK(role IN ('organizer')),PRIMARY KEY(organization_id,user_id));
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),slug text NOT NULL UNIQUE,title text NOT NULL,description text NOT NULL DEFAULT '',cover_path text,venue_name text NOT NULL,address text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,admission_starts_at timestamptz NOT NULL,admission_ends_at timestamptz NOT NULL,capacity integer NOT NULL CHECK(capacity>0),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','sales_closed','finished','cancelled')),created_by uuid REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now(),next_sequence integer NOT NULL DEFAULT 1,CHECK(ends_at>starts_at),CHECK(admission_ends_at>admission_starts_at));
CREATE TABLE event_staff(event_id uuid REFERENCES events(id),user_id uuid REFERENCES profiles(id),role text CHECK(role IN ('box_office','access_staff')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(event_id,user_id,role));
CREATE TABLE ticket_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),name text NOT NULL,capacity integer NOT NULL CHECK(capacity>0),active boolean NOT NULL DEFAULT true,UNIQUE(id,event_id),UNIQUE(event_id,name));
CREATE TABLE pricing_phases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_type_id uuid NOT NULL REFERENCES ticket_types(id),channel text NOT NULL CHECK(channel IN ('web','box_office')),name text NOT NULL,price_cop integer NOT NULL CHECK(price_cop>=0),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,CHECK(ends_at>starts_at));
CREATE FUNCTION prevent_phase_overlap() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM 1 FROM ticket_types WHERE id=NEW.ticket_type_id FOR UPDATE;
 IF NEW.active AND EXISTS(SELECT 1 FROM pricing_phases WHERE ticket_type_id=NEW.ticket_type_id AND channel=NEW.channel AND active AND id<>NEW.id AND starts_at<NEW.ends_at AND ends_at>NEW.starts_at) THEN RAISE EXCEPTION 'Fases superpuestas'; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase_overlap BEFORE INSERT OR UPDATE ON pricing_phases FOR EACH ROW EXECUTE FUNCTION prevent_phase_overlap();
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),buyer_user_id uuid REFERENCES profiles(id),buyer_name text,buyer_email text,buyer_phone text,buyer_category text,channel text NOT NULL CHECK(channel IN ('web','box_office','complimentary')),status text NOT NULL CHECK(status IN ('pending_payment','confirmed','expired','cancelled','partially_refunded','refunded','needs_review')),reservation_expires_at timestamptz,subtotal_cop integer NOT NULL CHECK(subtotal_cop>=0),fees_cop integer NOT NULL DEFAULT 0 CHECK(fees_cop>=0),total_cop integer NOT NULL CHECK(total_cop>=0),created_by uuid REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now(),idempotency_key uuid NOT NULL UNIQUE,share_hash text,share_encrypted text,UNIQUE(id,event_id),CHECK(total_cop=subtotal_cop+fees_cop));
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL,event_id uuid NOT NULL,ticket_type_id uuid NOT NULL,pricing_phase_id uuid REFERENCES pricing_phases(id),quantity integer NOT NULL CHECK(quantity>0),unit_price_cop integer NOT NULL CHECK(unit_price_cop>=0),line_total_cop integer NOT NULL CHECK(line_total_cop>=0),type_name text NOT NULL,phase_name text NOT NULL,FOREIGN KEY(order_id,event_id) REFERENCES orders(id,event_id),FOREIGN KEY(ticket_type_id,event_id) REFERENCES ticket_types(id,event_id),UNIQUE(id,event_id,ticket_type_id),CHECK(line_total_cop=quantity*unit_price_cop));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),provider text NOT NULL,method text NOT NULL,provider_transaction_id text UNIQUE,reference text NOT NULL UNIQUE,amount_cop integer NOT NULL CHECK(amount_cop>=0),currency text NOT NULL DEFAULT 'COP' CHECK(currency='COP'),status text NOT NULL CHECK(status IN ('pending','approved','declined','error','voided')),verified_by uuid REFERENCES profiles(id),verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),cash_session_id uuid);
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),ticket_type_id uuid NOT NULL,order_item_id uuid NOT NULL,owner_user_id uuid REFERENCES profiles(id),event_sequence integer NOT NULL CHECK(event_sequence>0),visible_number text NOT NULL,security_serial text NOT NULL UNIQUE,credential_hash text NOT NULL UNIQUE,credential_encrypted text NOT NULL,credential_version integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'valid' CHECK(status IN ('valid','used','cancelled')),issued_at timestamptz NOT NULL DEFAULT now(),used_at timestamptz,refund_id uuid,FOREIGN KEY(order_item_id,event_id,ticket_type_id) REFERENCES order_items(id,event_id,ticket_type_id),UNIQUE(event_id,event_sequence),UNIQUE(event_id,visible_number));
CREATE TABLE check_in_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES events(id),ticket_id uuid REFERENCES tickets(id),operator_id uuid NOT NULL REFERENCES profiles(id),device_id text NOT NULL,gate_label text NOT NULL,result text NOT NULL CHECK(result IN ('accepted','already_used','cancelled','wrong_event','outside_admission_window','unknown_ticket','unauthorized')),attempted_at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL UNIQUE,reason text);
CREATE TABLE cash_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),operator_id uuid NOT NULL REFERENCES profiles(id),opening_cash_cop integer NOT NULL CHECK(opening_cash_cop>=0),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,declared_cash_cop integer CHECK(declared_cash_cop>=0),expected_cash_cop integer,difference_cop integer,notes text);
CREATE UNIQUE INDEX cash_session_active ON cash_sessions(event_id,operator_id) WHERE closed_at IS NULL;
ALTER TABLE payments ADD FOREIGN KEY(cash_session_id) REFERENCES cash_sessions(id);
CREATE TABLE cash_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cash_session_id uuid NOT NULL REFERENCES cash_sessions(id),payment_id uuid UNIQUE REFERENCES payments(id),type text NOT NULL CHECK(type IN ('sale','in','out','refund')),amount_cop integer NOT NULL CHECK(amount_cop>=0),reason text NOT NULL,created_by uuid REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),payment_id uuid REFERENCES payments(id),amount_cop integer NOT NULL CHECK(amount_cop>=0),status text NOT NULL CHECK(status IN ('recorded','completed')),reason text NOT NULL,external_reference text NOT NULL,created_by uuid REFERENCES profiles(id),completed_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE tickets ADD FOREIGN KEY(refund_id) REFERENCES refunds(id);
CREATE TABLE delivery_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),channel text NOT NULL DEFAULT 'email',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','failed')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz);
CREATE TABLE print_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES tickets(id),operator_id uuid NOT NULL REFERENCES profiles(id),status text NOT NULL CHECK(status IN ('requested','submitted','confirmed','failed')),is_reprint boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES profiles(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,safe_metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_webhook_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,deduplication_key text NOT NULL UNIQUE,processing_status text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE rate_limits(key text PRIMARY KEY,window_start timestamptz NOT NULL DEFAULT now(),requests integer NOT NULL DEFAULT 1);
CREATE INDEX orders_event_status ON orders(event_id,status,reservation_expires_at);
CREATE INDEX orders_buyer ON orders(buyer_user_id);
CREATE INDEX items_order ON order_items(order_id);
CREATE INDEX items_type ON order_items(ticket_type_id);
CREATE INDEX tickets_event_status ON tickets(event_id,status);
CREATE INDEX tickets_owner ON tickets(owner_user_id);
CREATE INDEX tickets_item ON tickets(order_item_id);
CREATE INDEX pricing_type_channel ON pricing_phases(ticket_type_id,channel,starts_at,ends_at);
CREATE INDEX payments_order ON payments(order_id);
CREATE INDEX access_event ON check_in_attempts(event_id,attempted_at);
CREATE INDEX delivery_pending ON delivery_jobs(status,next_attempt_at);
CREATE INDEX cash_movements_session ON cash_movements(cash_session_id);
CREATE INDEX audit_time ON audit_logs(created_at);
CREATE INDEX event_org ON events(organization_id);

CREATE TABLE IF NOT EXISTS schema_migrations(name text primary key, applied_at timestamptz default now());
INSERT INTO schema_migrations(name) VALUES('001_core.sql') ON CONFLICT DO NOTHING;
